-- AVENZA BENGALURU REPLACEMENT DATASET
-- -- Generated records; incident reports, stop coordinates and segment geometry are not official survey data.
-- This script REPLACES all existing rows in the ten base tables. It preserves schema objects.
-- BACK UP avenza_db before running. Execute once in MySQL Workbench.
USE avenza_db;
SET FOREIGN_KEY_CHECKS=0;
TRUNCATE TABLE infrastructure_audit;
TRUNCATE TABLE incidents;
TRUNCATE TABLE pedestrian_density;
TRUNCATE TABLE route_segments;
TRUNCATE TABLE segment_transport;
TRUNCATE TABLE segment_infrastructure;
TRUNCATE TABLE routes;
TRUNCATE TABLE road_segments;
TRUNCATE TABLE transport_stops;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS=1;


