-- List all unique road corridors

USE avenza_db;

-- 100 Feet Road, Indiranagar
INSERT INTO locality_road_segments (locality_id, segment_id)
SELECT l.locality_id, s.segment_id
FROM localities l
CROSS JOIN road_segments s
WHERE l.locality_name = 'Indiranagar'
AND s.road_name LIKE '100 Feet Road, Indiranagar%';

-- 30th Cross Road, Jayanagar
INSERT INTO locality_road_segments (locality_id, segment_id)
SELECT l.locality_id, s.segment_id
FROM localities l
CROSS JOIN road_segments s
WHERE l.locality_name = 'Jayanagar'
AND s.road_name LIKE '30th Cross Road, Jayanagar%';

