INSERT INTO locality_road_segments (locality_id, segment_id)
SELECT l.locality_id, s.segment_id
FROM localities l
JOIN road_segments s
ON (
    (l.locality_name = 'Indiranagar'
     AND (s.road_name LIKE '100 Feet Road, Indiranagar%'
          OR s.road_name LIKE 'CMH Road%'))

 OR (l.locality_name = 'Jayanagar'
     AND (s.road_name LIKE '30th Cross Road, Jayanagar%'
          OR s.road_name LIKE 'Jayanagar 4th Block 11th Main%'))

 OR (l.locality_name = 'BTM Layout'
     AND s.road_name LIKE 'BTM Layout 16th Main%')

 OR (l.locality_name = 'Domlur'
     AND s.road_name LIKE 'Intermediate Ring Road, Domlur%')

 OR (l.locality_name = 'Whitefield'
     AND s.road_name LIKE 'ITPL Main Road, Whitefield%')

 OR (l.locality_name = 'HSR Layout'
     AND s.road_name LIKE 'HSR Layout 27th Main%')

 OR (l.locality_name = 'Koramangala'
     AND s.road_name LIKE 'Koramangala 5th Block 80 Feet Road%')

 OR (l.locality_name = 'Marathahalli'
     AND s.road_name LIKE 'Outer Ring Road, Marathahalli%')
)
WHERE NOT EXISTS (
    SELECT 1
    FROM locality_road_segments m
    WHERE m.locality_id = l.locality_id
      AND m.segment_id = s.segment_id
);



INSERT INTO locality_road_segments (locality_id, segment_id)
SELECT l.locality_id, s.segment_id
FROM localities l
JOIN road_segments s
    ON s.road_name LIKE CONCAT(l.locality_name, ' — section%')
WHERE l.locality_name IN (
    'MG Road',
    'Old Airport Road',
    'Sarjapur Road'
)
AND NOT EXISTS (
    SELECT 1
    FROM locality_road_segments m
    WHERE m.locality_id = l.locality_id
      AND m.segment_id = s.segment_id
);




INSERT INTO locality_road_segments (locality_id, segment_id)
SELECT l.locality_id, s.segment_id
FROM localities l
JOIN road_segments s
ON (
    (l.locality_name = 'JP Nagar'
     AND (
        s.road_name LIKE 'Bannerghatta Road%'
        OR s.road_name LIKE 'Kanakapura Road%'
     ))
    OR
    (l.locality_name = 'Electronic City'
     AND s.road_name LIKE 'Hosur Road%')
)
WHERE NOT EXISTS (
    SELECT 1
    FROM locality_road_segments m
    WHERE m.locality_id = l.locality_id
      AND m.segment_id = s.segment_id
);




