INSERT IGNORE INTO locality_road_segments (locality_id, segment_id)

SELECT
    l.locality_id,
    s.segment_id
FROM (
    SELECT 'Banashankari' AS locality_name, 'Kanakapura Road%' AS road_pattern
    UNION ALL SELECT 'Banashankari 2nd Stage', 'Kanakapura Road%'
    UNION ALL SELECT 'Basavanagudi', 'Lalbagh Road%'
    UNION ALL SELECT 'Basaveshwaranagar', 'Mysore Road%'
    UNION ALL SELECT 'Bellandur', 'Sarjapur Road%'
    UNION ALL SELECT 'Bellandur', 'Outer Ring Road, Marathahalli%'
    UNION ALL SELECT 'Bommanahalli', 'Hosur Road%'
    UNION ALL SELECT 'Brookefield', 'ITPL Main Road, Whitefield%'
    UNION ALL SELECT 'Cunningham Road', 'Cubbon Road%'
    UNION ALL SELECT 'Ejipura', 'Koramangala 5th Block 80 Feet Road%'
    UNION ALL SELECT 'Girinagar', 'Mysore Road%'
    UNION ALL SELECT 'HAL 2nd Stage', 'Old Airport Road%'
    UNION ALL SELECT 'Jakkur', 'Bellary Road (Airport Road)%'
    UNION ALL SELECT 'Majestic', 'Mysore Road%'
    UNION ALL SELECT 'Majestic', 'Tumkur Road%'
    UNION ALL SELECT 'Malleshwaram', 'Tumkur Road%'
    UNION ALL SELECT 'Peenya', 'Tumkur Road%'
    UNION ALL SELECT 'Rajajinagar', 'Tumkur Road%'
    UNION ALL SELECT 'Ramamurthy Nagar', 'Old Madras Road%'
    UNION ALL SELECT 'RT Nagar', 'Bellary Road (Airport Road)%'
    UNION ALL SELECT 'Sadashivanagar', 'Bellary Road (Airport Road)%'
    UNION ALL SELECT 'Sahakara Nagar', 'Bellary Road (Airport Road)%'
    UNION ALL SELECT 'Vasanth Nagar', 'Kasturba Road%'
    UNION ALL SELECT 'Vijayanagar', 'Mysore Road%'
    UNION ALL SELECT 'Yeshwanthpur', 'Tumkur Road%'
) AS mapping
JOIN localities l
    ON l.locality_name = mapping.locality_name
JOIN road_segments s
    ON s.road_name LIKE mapping.road_pattern;